// 本人办理页只回原quote与命令；接受才实际一次换任，展示不触公库、Family或军团状态。
#include "political_head_handover_view.hpp"
#include "political_head_handover_detail.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;using A=V::Array;using D=V::Dict;using boundary::obj;
// 同候选身份只作显示与陈旧页拒绝，正式写入还须原提交门重报价。
V identity(const WorldIdentity& s){StableId id;constexpr char hex[]="0123456789abcdef";for(auto b:s.world_id){id+=hex[b>>4];id+=hex[b&15];}return obj({{"world_id",V{id}},{"execution_epoch",V{s.execution_epoch}},{"revision",V{s.revision}},{"tick",V{s.tick}}});}
// 对另一方尚未亲历的关闭原因只显示不可办理，不远程广播撤回人的新行为。
V action(const PoliticalHeadHandoverBusinessContext& x,const StableId& actor,const PoliticalHeadHandoverCommand& c,const StableId& label){auto q=preview_political_head_handover_business(x,actor,c);auto code=q.ok?StableId{}:q.error.original.code;if(code=="PoliticalHeadHandoverAlreadyClosed")code="PoliticalHeadHandoverUnavailable";return obj({{"text",V{label}},{"command",V{political_head_handover_command_kind(c)}},{"params",encode_political_head_handover_command(c)},{"available",V{q.ok}},{"code",V{code}}});}
}
BoundaryValue encode_political_head_handover_quote(const PoliticalHeadHandoverQuote& q){return obj({{"source_identity",identity(q.identity)},{"actor_id",V{q.actor_id}},{"duration",V{Integer{0}}},{"command_kind",V{political_head_handover_command_kind(q.command)}},{"params",encode_political_head_handover_command(q.command)},{"scope",V{"原首任签署有限期让职；双方同在首府时本人接受，一次换任原首职。私产、军令和玩家控制不随之交割。"}}});}
Outcome<BoundaryValue> query_political_head_handovers(const PoliticalHeadHandoverBusinessContext& view,const StableId& place,Integer cursor){const auto& x=view.rules;const auto& common=x.common;const auto actor=common.state().metadata.player_actor_id;auto here=politics_detail::place(common,actor);if(!here||here->place_id!=place)return {false,{},common_failure("PoliticalHeadHandoverLocalQueryRequired",place).error};if(cursor<0||cursor>std::numeric_limits<Integer>::max()-16)return {false,{},common_failure("PoliticalHeadHandoverCursorInvalid").error};auto v=politics_detail::available(common,x.activity,actor);if(!v.ok)return {false,{},v.error};v=validate_political_head_handovers(view);if(!v.ok)return {false,{},v.error};A rows;Integer count=0;auto append=[&](auto build){auto i=count++;if(i>=cursor&&i<cursor+16)rows.push_back(build());};
 for(const auto& row:x.catalog.policies.rows()){const auto& p=row.second;const auto* original=x.succession_catalog.policies.find(p.succession_policy_id);if(!original||original->seat_place_id!=place)continue;auto office=read_political_head_handover_current_office(x,*original);if(!office.ok)return {false,{},office.error};if(office.value.holder_actor_id!=std::optional<StableId>{actor}||office.value.original_leader_actor_id!=actor)continue;
  for(const auto& candidate:common.state().actors.rows()){if(candidate.first==actor)continue;auto local=politics_detail::place(common,candidate.first);if(!local||local->place_id!=place||!head_handover_detail::contact(x,*original,candidate.first).ok||!(x.state.version==2?validate_head_handover_person2(x,candidate.first,{}):growth_independent_office_age(common,candidate.first)).ok||!head_handover_detail::member_now(x,*original,candidate.first).ok)continue;append([&]{PoliticalOfferHeadHandover c{{original->organization_id,original->leader_office_id,office.value.office_epoch,actor},p.id,candidate.first,office.value.office_epoch};return obj({{"kind",V{"handover_option"}},{"policy_id",V{p.id}},{"candidate_actor_id",V{candidate.first}},{"actions",V{A{action(view,actor,c,"明确签署生前让职意愿")}}}});});}
 }
 for(const auto& row:x.state.offers.rows()){const auto& offer=row.second;if(offer.issuer_actor_id!=actor&&offer.candidate_actor_id!=actor)continue;const auto* p=x.catalog.policies.find(offer.policy_id);const auto* original=p?x.succession_catalog.policies.find(p->succession_policy_id):nullptr;if(!original||original->seat_place_id!=place)continue;
  append([&]{A known,actions;bool personally_closed=false;for(const auto& answer:x.state.answers.rows())if(answer.second.offer_fact_id==offer.id&&(answer.second.accepted||answer.second.actor_id==actor)){known.push_back(obj({{"id",V{answer.first}},{"accepted",V{answer.second.accepted}},{"tick",V{answer.second.tick}}}));personally_closed=true;}D r{{"kind",V{"known_handover"}},{"offer_fact_id",V{offer.id}},{"policy_id",V{offer.policy_id}},{"issuer_actor_id",V{offer.issuer_actor_id}},{"candidate_actor_id",V{offer.candidate_actor_id}},{"response_until",V{offer.response_until}},{"known_answers",V{std::move(known)}}};if(actor==offer.issuer_actor_id)for(const auto& w:x.state.withdrawals.rows())if(w.second.offer_fact_id==offer.id){r.push_back({"own_withdrawal_fact_id",V{w.first}});personally_closed=true;}if(!personally_closed){if(actor==offer.candidate_actor_id){actions.push_back(action(view,actor,PoliticalAnswerHeadHandover{offer.id,true,offer.office_epoch},"本人接受并办理原首职交接"));actions.push_back(action(view,actor,PoliticalAnswerHeadHandover{offer.id,false,offer.office_epoch},"本人明确谢绝本次让职"));}else actions.push_back(action(view,actor,PoliticalWithdrawHeadHandover{{offer.organization_id,offer.office_id,offer.office_epoch,actor},offer.id},"原首任明确撤回尚未执行的意愿"));}r.push_back({"actions",V{std::move(actions)}});return V{std::move(r)};});
 }
 if(cursor>count)return {false,{},common_failure("PoliticalHeadHandoverCursorInvalid").error};D page{{"ok",V{true}},{"source_identity",identity(common.state().identity)},{"observer_actor_id",V{actor}},{"place_id",V{place}},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(count>cursor+16)page.push_back({"next_cursor",V{cursor+16}});return {true,V{std::move(page)},{}};
}
}
